	return System.Math.Round((decimal)e.Podstawa2.Value, 2);
}

public decimal Get_Feature_Budżet_kwota(Context cx) {
	// Kolumna widoku rezerwy urlopowej na liście Pracownicy.
	// Miesiąc rezerwy = miesiąc daty aktualności listy.
	Date data = ActualDate.Today(cx);

	// Ostatnio naliczona pozycja elementu "Budżet rezerwy urlopowej" pracownika na planowanej liście płac za ten miesiąc
	PlaceModule place = PlaceModule.GetInstance(Session);
	PlanowanyElementWypłaty e = null;
	foreach (PlanowanyElementWypłaty p in place.PlanElementyWyp.WgPracownik[(Pracownik)Row]) {
		if (p.Definicja == null || p.Definicja.Nazwa != "Budżet rezerwy urlopowej")
			continue;
		if (p.Okres.To.Year != data.Year || p.Okres.To.Month != data.Month)
			continue;
		if (e == null || p.ID > e.ID)
			e = p;
	}
	if (e == null)
		return 0m;
	return System.Math.Round((decimal)e.Wartosc, 2);
}

